import sys, threading
WS = "/user/user1/harbor-runs/9406560323f5/workspace"
sys.path.insert(0, WS + "/verl")
sys.path.insert(0, WS + "/third_party/python")
from verl.utils.reward_score import math_verify as verl_mv

cases = [
    ("Therefore, the final answer is: \\boxed{625}.", "625"),
    ("The final answer is \\(\\boxed{1293}\\)", "1293"),
    ("answer \\boxed{2}", "x = 2"),
]
print("main-thread scoring:")
for out, gt in cases:
    try:
        print("  ", gt, "->", verl_mv.compute_score(out, gt))
    except Exception as e:
        print("  ", gt, "-> EXC", type(e).__name__, str(e)[:120])

print("worker-thread scoring:")
results = {}
def work(idx, out, gt):
    try:
        results[idx] = ("ok", verl_mv.compute_score(out, gt))
    except Exception as e:
        results[idx] = ("exc", f"{type(e).__name__}: {str(e)[:160]}")
threads = []
for i, (out, gt) in enumerate(cases):
    t = threading.Thread(target=work, args=(i, out, gt))
    t.start(); threads.append(t)
for t in threads: t.join()
for i in sorted(results):
    print("  ", cases[i][1], "->", results[i])
EOF
cd /tmp/diag && python3 -I test_threaded.py

